// Optional first-party counters. No address, name, email, URL query, IP or device fingerprint is sent.
const KEY='moneyLabAnalyticsBrowser.v1',OFF='moneyLabAnalyticsOff.v1',TEST='moneyLabAnalyticsTest.v1';
const tr=(vi,en)=>document.documentElement.lang==='en'?en:vi;
export function analyticsHeaders(){try{return localStorage.getItem(TEST)==='1'?{'X-MoneyLab-Analytics-Test':'1'}:{};}catch{return {};}}
function browserKey(){try{let k=localStorage.getItem(KEY);if(!/^[a-f0-9]{64}$/.test(k||'')){k=[...crypto.getRandomValues(new Uint8Array(32))].map(v=>v.toString(16).padStart(2,'0')).join('');localStorage.setItem(KEY,k);}return k;}catch{return null;}}
export function track(metric,mode,level='all',eventId=crypto.randomUUID(),value=1){try{if(localStorage.getItem(OFF)==='1')return;const browser=browserKey();if(!browser)return;fetch('/api/analytics/event',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json',...analyticsHeaders()},body:JSON.stringify({browser,eventId,metric,mode,level,value}),keepalive:true}).catch(()=>{});}catch{}}
export function trackSolo(before,next){
 if(!before?.started&&next.started)track('stage_started','guest_solo',next.difficulty,next.runId);
 else if(before?.runId&&next.runId!==before.runId){if(before.phase!=='finished')track('stage_abandoned','guest_solo',before.difficulty,before.runId);if(next.started)track('stage_started','guest_solo',next.difficulty,next.runId);}
 if(next.phase==='finished'&&before.phase!=='finished'&&next.labResult){const r=next.labResult;track('stage_finished','guest_solo',next.difficulty,next.runId);track('score','guest_solo',next.difficulty,next.runId,r.points);if(r.survived)track('stage_survived','guest_solo',next.difficulty,next.runId);if(r.won)track('stage_won','guest_solo',next.difficulty,next.runId);}
}
export function trackLocal(before,next){
 for(let i=0;i<next.players.length;i++){const b=before.players[i]?.game,g=next.players[i].game;if(!g?.runId)continue;const id=browserKey()+'|'+g.runId+'|'+i;if(next.active&&(!before.active||before.round!==next.round))track('stage_started','local_group',g.difficulty,id);if(b?.phase!=='finished'&&g.phase==='finished'){if(g.competitionAbandoned)track('stage_abandoned','local_group',g.difficulty,id);else if(g.labResult){track('stage_finished','local_group',g.difficulty,id);track('score','local_group',g.difficulty,id,g.labResult.points);if(g.labResult.survived)track('stage_survived','local_group',g.difficulty,id);if(g.labResult.won)track('stage_won','local_group',g.difficulty,id);}}}
}
export function mountAnalytics(){
 try{const u=new URL(location.href);if(u.searchParams.get('ml_test')==='1')localStorage.setItem(TEST,'1');if(u.searchParams.get('ml_test')==='0')localStorage.removeItem(TEST);}catch{}
 const host=document.createElement('details');host.className='analytics-notice';host.style.cssText='max-width:1156px;margin:18px auto;padding:12px 18px;color:#52736b;font-size:12px';const summary=document.createElement('summary'),p=document.createElement('p'),label=document.createElement('label'),check=document.createElement('input');check.type='checkbox';label.append(check,document.createTextNode(' '));const text=document.createElement('span');label.append(text);host.append(summary,p,label);document.body.append(host);
 function render(){summary.textContent=tr('Thống kê trò chơi & quyền riêng tư','Game statistics & privacy');p.textContent=tr('Thống kê nội bộ ghi nhận lượt mở trang, bắt đầu/kết thúc chặng, cấp độ và điểm bằng mã trình duyệt ngẫu nhiên. Không gửi tên, email hay địa chỉ ví trong báo cáo. Chơi khách chỉ là dữ liệu trình duyệt báo về; không được coi là người thật đã xác minh. Hồ sơ ví/online vẫn lưu tiến trình cần thiết; báo cáo chỉ dùng tổng hợp. Chi tiết sự kiện giả danh được dọn sau 90 ngày khi hệ thống cập nhật thống kê; tổng hợp không định danh được giữ lại.','First-party counters record page opens, stage starts/ends, level and score using a random browser identifier. Reports contain no names, emails or wallet addresses. Guest activity is client-reported, not verified human usage. Wallet/online profiles still save required progress; reporting is aggregate only. Pseudonymous event details are pruned after 90 days during statistics refresh; non-identifying totals remain.');text.textContent=tr('Cho phép thống kê trình duyệt (tắt sẽ xóa chi tiết sự kiện gắn với mã trình duyệt này)','Allow browser statistics (turning off removes event details linked to this browser identifier)');try{check.checked=localStorage.getItem(OFF)!=='1';}catch{check.checked=false;}}
 check.onchange=()=>{try{if(check.checked){localStorage.removeItem(OFF);track('page_view','site');}else{const browser=localStorage.getItem(KEY);localStorage.setItem(OFF,'1');if(browser)fetch('/api/analytics/event',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({browser,eventId:crypto.randomUUID(),metric:'forget'}),keepalive:true}).catch(()=>{});localStorage.removeItem(KEY);}}catch{}render();};render();new MutationObserver(render).observe(document.documentElement,{attributes:true,attributeFilter:['lang']});track('page_view','site');
}
